package com.myaaptha.domain.trust;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;import com.fasterxml.jackson.databind.*;import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.http.*;import org.springframework.mock.web.MockMultipartFile;import org.springframework.test.web.servlet.*;
@SpringBootTest @AutoConfigureMockMvc class TrustControllerTest{@Autowired MockMvc mvc;@Autowired ObjectMapper json;
 @Test void emergencyRequiresTwoStarsAndRoleModelHidesContactDetails()throws Exception{JsonNode owner=user("trust-owner","+15550770101","Trust","Owner"),star1=user("trust-star1","+15550770102","First","Star"),star2=user("trust-star2","+15550770103","Second","Star"),follower=user("trust-follower","+15550770104","Role","Follower");String ot=login(owner),s1=login(star1),s2=login(star2),ft=login(follower);add(ot,star1.get("id").asLong(),"STAR");add(ot,star2.get("id").asLong(),"STAR");add(ot,star1.get("id").asLong(),"ROLE_MODEL");mvc.perform(get("/api/trust/role-models").header(HttpHeaders.AUTHORIZATION,b(ft))).andExpect(status().isOk()).andExpect(jsonPath("$[0].displayName").value("First Star")).andExpect(jsonPath("$[0].phoneNumber").doesNotExist()).andExpect(jsonPath("$[0].email").doesNotExist());mvc.perform(post("/api/trust/role-models/"+star1.get("id").asLong()+"/follow").header(HttpHeaders.AUTHORIZATION,b(ft))).andExpect(status().isOk()).andExpect(jsonPath("$.followerCount").value(1));MvcResult post=mvc.perform(multipart("/api/social/posts").file(new MockMultipartFile("file","medical.pdf","application/pdf",new byte[]{37,80,68,70,45,49,46,52})).param("caption","Private medical document").param("audience","PRIVATE").header(HttpHeaders.AUTHORIZATION,b(ot))).andExpect(status().isOk()).andReturn();long postId=json.readTree(post.getResponse().getContentAsString()).get("id").asLong();MvcResult request=mvc.perform(post("/api/trust/emergencies").header(HttpHeaders.AUTHORIZATION,b(s1)).contentType(MediaType.APPLICATION_JSON).content("{\"ownerUserId\":"+owner.get("id").asLong()+",\"reason\":\"Owner is unconscious in hospital and doctors need records\"}")).andExpect(status().isOk()).andExpect(jsonPath("$.status").value("PENDING")).andExpect(jsonPath("$.approvals").value(1)).andReturn();long id=json.readTree(request.getResponse().getContentAsString()).get("id").asLong();mvc.perform(get("/api/trust/emergencies/"+id+"/documents").header(HttpHeaders.AUTHORIZATION,b(s1))).andExpect(status().isForbidden());mvc.perform(post("/api/trust/emergencies/"+id+"/decision").header(HttpHeaders.AUTHORIZATION,b(s2)).contentType(MediaType.APPLICATION_JSON).content("{\"approved\":true}")).andExpect(status().isOk()).andExpect(jsonPath("$.status").value("APPROVED")).andExpect(jsonPath("$.approvals").value(2));mvc.perform(get("/api/trust/emergencies/"+id+"/documents").header(HttpHeaders.AUTHORIZATION,b(s1))).andExpect(status().isOk()).andExpect(jsonPath("$[0].id").value(postId));mvc.perform(get("/api/trust/emergencies/"+id+"/documents/"+postId+"/media").header(HttpHeaders.AUTHORIZATION,b(s1))).andExpect(status().isOk()).andExpect(content().contentType("application/pdf"));mvc.perform(get("/api/trust/emergencies/"+id+"/documents").header(HttpHeaders.AUTHORIZATION,b(ft))).andExpect(status().isForbidden());}
 private void add(String token,long id,String kind)throws Exception{mvc.perform(post("/api/trust/people").header(HttpHeaders.AUTHORIZATION,b(token)).contentType(MediaType.APPLICATION_JSON).content("{\"userId\":"+id+",\"kind\":\""+kind+"\"}")).andExpect(status().isOk());}private JsonNode user(String username,String phone,String first,String last)throws Exception{MvcResult r=mvc.perform(post("/api/users").contentType(MediaType.APPLICATION_JSON).content(json.writeValueAsString(new P(username,phone,"secret123",first,last,"Test")))).andExpect(status().isOk()).andReturn();return json.readTree(r.getResponse().getContentAsString());}private String login(JsonNode u)throws Exception{MvcResult r=mvc.perform(post("/api/auth/login").contentType(MediaType.APPLICATION_JSON).content("{\"identifier\":\""+u.get("phoneNumber").asText()+"\",\"password\":\"secret123\"}")).andExpect(status().isOk()).andReturn();return json.readTree(r.getResponse().getContentAsString()).get("accessToken").asText();}private String b(String t){return "Bearer "+t;}private record P(String username,String phoneNumber,String password,String firstName,String surname,String location){}
}
